  function bankDasDass() {
    return Core.shuffle(DAS_DASS).map(([sentence, correct, explain]) => {
      const opts = ["das", "dass"];
      return {
        prompt: sentence,
        options: opts,
        correct: [opts.indexOf(correct)],
        explain,
      };
    });
  }

